import {CutoutPlayer} from './cutout-player.mjs';
import {CharacterSkillController} from '../character-skill-runtime.mjs';
import {recordCharacterVideo} from './export-tools.mjs';
export async function recordSkillPreview(pack,project,options){
 const skill=Object.values(pack.skills)[0],clip=pack.animations[skill.animationId],clips=Object.fromEntries(['idle','walk','run','attack'].map(id=>[id,{...structuredClone(clip),id:id==='attack'?clip.id:'reference-'+id,kind:id==='attack'?'attack':'loop'}])),spec={format:'cutout-character-v1',rig:project.rig,parts:project.parts,headId:project.headId,bodyId:project.bodyId,mountSignatures:project.mountSignatures,attachments:project.attachments,weapon:{grip:.12,wtype:'sword',sprite:'reference_unused',restAng:1.2,stance:-.7},clips};
 const player=await CutoutPlayer.load(spec);try{if(pack.weapons)await player.addAccessories(pack.weapons);const controller=await CharacterSkillController.load(player,pack,{ownedSkills:[skill.id]}),canvas=Object.assign(document.createElement('canvas'),{width:720,height:720}),ctx=canvas.getContext('2d');const cast=controller.cast(skill.id);if(!cast.ok)throw Error('Không thử được chiêu: '+cast.reason);return await recordCharacterVideo(canvas,skill.duration,t=>{controller.seek(t);ctx.clearRect(0,0,720,720);const g=ctx.createLinearGradient(0,0,0,720);g.addColorStop(0,'#162334');g.addColorStop(1,'#27463e');ctx.fillStyle=g;ctx.fillRect(0,0,720,720);ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(360,563,43,12,0,0,Math.PI*2);ctx.fill();controller.draw(ctx,360,560,2.2);ctx.fillStyle='#0b121ee8';ctx.fillRect(0,646,720,74);ctx.fillStyle='#d3ed92';ctx.font='bold 18px system-ui';ctx.fillText(skill.name,18,670,680);ctx.fillStyle='#dce3ec';ctx.font='11px monospace';ctx.fillText('animationId: '+skill.animationId,18,690,680);ctx.fillText('weaponId: '+(skill.weaponId||'none')+' · skillId: '+skill.id,18,708,680)},options)}finally{player.dispose()}
}
